// Target-tier content (majority, 70%) — "master" rank, authored first.
export const SENIOR_QUESTION_POOLS_TARGET = {};
for (const lessonId of Object.keys(RAW)) {
  SENIOR_QUESTION_POOLS_TARGET[lessonId] = tagLesson(lessonId, RAW[lessonId], "master", "senior_master");
}

export function getTargetTierQuestionPoolForLessons(lessonIds, lang) {
  const safeLang = LANGS.includes(lang) ? lang : "fr";
  const out = [];
  for (const lessonId of lessonIds) {
    const pool = SENIOR_QUESTION_POOLS_TARGET[lessonId];
    if (pool && pool[safeLang]) out.push(...pool[safeLang]);
  }
  return out;
}

// Kept as an alias for backward compatibility with the current (pre-2-tier)
// examEngine.ts wiring, which still only knows about the master tier. Update
// examEngine.ts to consume both tiers (weighted 70/30) once this content is
// validated — not done in this pass, content-authoring only.
export const SENIOR_QUESTION_POOLS = SENIOR_QUESTION_POOLS_TARGET;
export const getSeniorQuestionPoolForLessons = getTargetTierQuestionPoolForLessons;

// Preceding-rank-tier content (minority, 30%) — "chief_officer" rank, the
// rank immediately before "master" on the Deck ladder. Not yet consumed by
